//! Byte-exact tests for the #67 candidate-entry derivation.
//!
//! These test vectors are synthetic derivation fixtures, not verified proofs
//! or registration alignments. They are independently generated using the
//! `scripts/gen_test_vectors_67.py` script (Python 3.8+, cbor2 >= 6.0) and hardcoded
//! here. The Rust implementation must reproduce the exact expected bytes.
//!
//! See `scripts/gen_test_vectors_67.py` for the generator
//! and `pask_-04_design_67_v3_consolidated.md` for the design.

#![cfg(test)]

use pask_wire::derive_candidate_entry;

fn hex_decode(s: &str) -> Vec<u8> {
    let bytes = (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap());
    bytes.collect()
}

