// ===========================================================================
// Tests
// ===========================================================================

#[test]
fn tv1_standard_untagged() {
    let cose = hex_decode(TV1_COSE);
    let expected = hex_decode(TV1_CANDIDATE);
    let result = derive_candidate_entry(&cose).unwrap();
    assert_eq!(result, expected);
}

#[test]
fn tv2_tag_18_wrapped() {
    let cose = hex_decode(TV2_COSE);
    let expected = hex_decode(TV1_CANDIDATE);
    let result = derive_candidate_entry(&cose).unwrap();
    assert_eq!(result, expected);
}

#[test]
fn tv3_one_receipt_acceptance_invariant() {
    let cose = hex_decode(TV3_COSE);
    let expected = hex_decode(TV1_CANDIDATE);
    let result = derive_candidate_entry(&cose).unwrap();
    assert_eq!(result, expected);
}

#[test]
fn tv4_two_receipts_acceptance_invariant() {
    let cose = hex_decode(TV4_COSE);
    let expected = hex_decode(TV1_CANDIDATE);
    let result = derive_candidate_entry(&cose).unwrap();
    assert_eq!(result, expected);
}

#[test]
fn tv5_tampered_payload() {
    let cose = hex_decode(TV5_COSE);
    let result = derive_candidate_entry(&cose).unwrap();
    // Must differ from TV1 candidate entry
    assert_ne!(result, hex_decode(TV1_CANDIDATE));
}

#[test]
fn tv1_leaf_hash() {
    let cose = hex_decode(TV1_COSE);
    let candidate = derive_candidate_entry(&cose).unwrap();
    let leaf = pask_wire::candidate_leaf_hash(&candidate);
    assert_eq!(hex::encode(leaf), TV1_LEAF);
}

#[test]
fn tv5_leaf_hash() {
    let cose = hex_decode(TV5_COSE);
    let candidate = derive_candidate_entry(&cose).unwrap();
    let leaf = pask_wire::candidate_leaf_hash(&candidate);
    assert_eq!(hex::encode(leaf), TV5_LEAF);
}

#[test]
fn tv1_receipts_share_leaf_hash() {
    let cose1 = hex_decode(TV1_COSE);
    let cose3 = hex_decode(TV3_COSE);
    let cose4 = hex_decode(TV4_COSE);

    let candidate1 = derive_candidate_entry(&cose1).unwrap();
    let candidate3 = derive_candidate_entry(&cose3).unwrap();
    let candidate4 = derive_candidate_entry(&cose4).unwrap();

    assert_eq!(candidate1, candidate3);
    assert_eq!(candidate1, candidate4);
}

#[test]
fn tv5_differs_from_tv1() {
    let cose1 = hex_decode(TV1_COSE);
    let cose5 = hex_decode(TV5_COSE);
    let candidate1 = derive_candidate_entry(&cose1).unwrap();
    let candidate5 = derive_candidate_entry(&cose5).unwrap();
    assert_ne!(candidate1, candidate5);
}

